url_options.data:
{
  "size": 0,
  "query": {
    "bool": {
      "filter": [
        {
          "range": {
            "@timestamp": {
              "gte": "${__from}",
              "lte": "${__to}"
            }
          }
        },
        {
          "wildcard": {
            "session.media.id": "${media_id}"
          }
        },
        {
          "wildcard": {
            "session.player.platform": "${platform}"
          }
        },
        {
          "term": {
            "event_name": "ERROR"
          }
        },
        {
          "term": {
            "data.business_error": false
          }
        },
        {
          "wildcard": {
            "data.url": "*hdntl=*"
          }
        }
      ]
    }
  },
  "aggs": {
    "by_token": {
      "terms": {
        "script": {
          "lang": "painless",
          "source": "String u = doc['data.url'].value; int i = u.indexOf('hmac='); if (i < 0) { return 'no-hmac'; } int s = i + 5; int e = u.indexOf('/', s); if (e < 0) { e = u.length(); } return u.substring(s, e);"
        },
        "size": 10000,
        "order": {
          "ips": "desc"
        }
      },
      "aggs": {
        "sessions": {
          "cardinality": {
            "field": "session_id"
          }
        },
        "ips": {
          "cardinality": {
            "field": "user_ip"
          }
        },
        "shared_only": {
          "bucket_selector": {
            "buckets_path": {
              "nips": "ips"
            },
            "script": "params.nips > 1"
          }
        }
      }
    },
    "total_tokens": {
      "cardinality": {
        "script": {
          "lang": "painless",
          "source": "String u = doc['data.url'].value; int i = u.indexOf('hmac='); if (i < 0) { return 'no-hmac'; } int s = i + 5; int e = u.indexOf('/', s); if (e < 0) { e = u.length(); } return u.substring(s, e);"
        },
        "precision_threshold": 40000
      }
    },
    "shared_tokens": {
      "stats_bucket": {
        "buckets_path": "by_token>ips"
      }
    },
    "affected_sessions": {
      "sum_bucket": {
        "buckets_path": "by_token>sessions"
      }
    },
    "affected_ips": {
      "sum_bucket": {
        "buckets_path": "by_token>ips"
      }
    }
  }
}

